/// Re-derives deployment authority from canonical review state and a verified
/// content-addressed bundle manifest. The manifest bytes and artifact entries
/// must be hash-verified by the persistence adapter before this call.
pub fn reviewed_deployment_authority(
    case_space: &CaseSpace,
    claim_cell_id: &str,
    bundle: &VerifiedDeploymentBundle,
) -> Result<ReviewedDeploymentAuthority, CompilerFinding> {
    let manifest = bundle.manifest();
    let deployment_bundle_hash = bundle.manifest_content_hash();
    let CompilationMode::Reviewed(binding) = reviewed_compilation_mode(case_space, claim_cell_id)?
    else {
        unreachable!("reviewed_compilation_mode only returns reviewed authority")
    };
    let mismatch = |location: &str, detail: &str| {
        compiler_finding("reviewed_deployment_binding_mismatch", location, detail)
    };
    if manifest.schema != DEPLOYMENT_BUNDLE_SCHEMA
        || !matches!(
            manifest.compiler_version.as_str(),
            GRAPH_COMPILER_VERSION | LEGACY_GRAPH_COMPILER_VERSION_V0
        )
        || manifest.mode != "reviewed"
    {
        return Err(mismatch(
            "$.manifest",
            "bundle is not a reviewed deployment manifest from a supported exact compiler profile",
        ));
    }
    if manifest.compiler_version != binding.compiler_version {
        return Err(mismatch(
            "$.manifest.compiler_version",
            "bundle compiler profile differs from the profile accepted by the topology review",
        ));
    }
    let manifest_compiler = if manifest.compiler_version == GRAPH_COMPILER_VERSION {
        let identity = manifest.compiler_identity.as_ref().ok_or_else(|| {
            mismatch(
                "$.manifest.compiler_identity",
                "current compiler bundle omits its reviewed semantic identity",
            )
        })?;
        let contracts = manifest
            .compiler_input_contract_versions
            .as_ref()
            .ok_or_else(|| {
                mismatch(
                    "$.manifest.compiler_input_contract_versions",
                    "current compiler bundle omits its semantic contract inventory",
                )
            })?;
        CompilerReviewIdentity {
            compiler_version: manifest.compiler_version.clone(),
            semantic_profile: identity.semantic_profile.clone(),
            compiler_inputs_schema: contracts.compiler_inputs.clone(),
            contract_versions_content_hash: crate::native_hash::sha256_hex(
                &canonical_json_bytes(contracts).expect("typed compiler contracts serialize"),
            ),
        }
    } else {
        legacy_compiler_review_identity_v0()
    };
    if manifest_compiler.semantic_profile != binding.compiler_semantic_profile
        || manifest_compiler.compiler_inputs_schema != binding.compiler_inputs_schema
        || manifest_compiler.contract_versions_content_hash
            != binding.compiler_contract_versions_content_hash
    {
        return Err(mismatch(
            "$.manifest.compiler_identity",
            "bundle compiler semantics differ from the accepted topology review",
        ));
    }
    if manifest.case_space_id != binding.case_space_id
        || manifest.base_revision_id != binding.base_revision_id
        || manifest.accepted_review_revision_id.as_deref()
            != Some(binding.base_revision_id.as_str())
    {
        return Err(mismatch(
            "$.manifest.base_revision_id",
            "bundle is not bound to the accepted review revision",
        ));
    }
    if manifest.topology_content_hash != binding.topology_content_hash {
        return Err(mismatch(
            "$.manifest.topology_content_hash",
            "bundle topology differs from the accepted topology review",
        ));
    }
    if manifest.policy_manifest_content_hash != binding.policy_manifest_content_hash {
        return Err(mismatch(
            "$.manifest.policy_manifest_content_hash",
            "bundle policies differ from the accepted topology review",
        ));
    }
    if manifest.reviewed_claim_cell_id.as_deref() != Some(claim_cell_id)
        || manifest.accepted_review_id.as_deref() != Some(binding.review_id.as_str())
    {
        return Err(mismatch(
            "$.manifest.accepted_review_id",
            "bundle does not name the canonical accepted topology review",
        ));
    }
    if deployment_bundle_hash.len() != 64
        || !deployment_bundle_hash
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(compiler_finding(
            "invalid_deployment_bundle_hash",
            "$.deployment_bundle_hash",
            "deployment bundle hash must be a lowercase SHA-256 hex digest",
        ));
    }
    Ok(ReviewedDeploymentAuthority {
        claim_cell_id: claim_cell_id.to_owned(),
        accepted_review_id: binding.review_id,
        topology_content_hash: binding.topology_content_hash,
        policy_manifest_content_hash: binding.policy_manifest_content_hash,
        deployment_bundle_hash: deployment_bundle_hash.to_owned(),
        accepted_review_revision_id: binding.base_revision_id,
        case_space_id: binding.case_space_id,
    })
}

#[test]
fn builds_review_morphisms_for_all_explicit_outcomes() {
    let space = fixture_space_with_completion();

    let accepted = accept_review_morphism(
        &space,
        request(
            NativeReviewTargetKind::Completion,
            "completion:source-backed-evidence",
            ReviewAction::Reject,
            "revision:accept",
        ),
    )
    .expect("accept completion");
    let rejected = reject_review_morphism(
        &space,
        request(
            NativeReviewTargetKind::Evidence,
            "evidence:source-backed",
            ReviewAction::Accept,
            "revision:reject",
        ),
    )
    .expect("reject evidence");
    let reopened = reopen_review_morphism(
        &space,
        request(
            NativeReviewTargetKind::Morphism,
            "morphism:generated",
            ReviewAction::Accept,
            "revision:reopen",
        ),
    )
    .expect("reopen morphism");
    let deferred = defer_review_morphism(
        &space,
        request(
            NativeReviewTargetKind::Waiver,
            "relation:needs-evidence",
            ReviewAction::Accept,
            "revision:defer",
        ),
    )
    .expect("defer waiver");

    assert_eq!(accepted.morphism_type, CaseMorphismType::Review);
    assert_eq!(accepted.metadata["action"], json!("accept"));
    assert_eq!(
        rejected.metadata["outcome_review_status"],
        json!("rejected")
    );
    assert_eq!(
        reopened.metadata["outcome_review_status"],
        json!("unreviewed")
    );
    assert_eq!(deferred.metadata["action"], json!("defer"));
    assert_eq!(accepted.added_ids, Vec::<Id>::new());
}

#[test]
fn historical_topology_review_without_compiler_fields_replays_as_profile_zero() {
    let space = fixture_space();
    let (_, _, current) = topology_review_target(&space);
    let mut historical = serde_json::to_value(current).expect("review target serializes");
    let object = historical
        .as_object_mut()
        .expect("review target is an object");
    object.remove("compiler_version");
    object.remove("compiler_semantic_profile");
    object.remove("compiler_inputs_schema");
    object.remove("compiler_contract_versions_content_hash");

    let replayed: ExecutionTopologyReviewTarget =
        serde_json::from_value(historical).expect("historical review target replays");
    let legacy = crate::graph_compiler::legacy_compiler_review_identity_v0();
    assert_eq!(replayed.compiler_version, legacy.compiler_version);
    assert_eq!(replayed.compiler_semantic_profile, legacy.semantic_profile);
    assert_eq!(
        replayed.compiler_inputs_schema,
        legacy.compiler_inputs_schema
    );
    assert_eq!(
        replayed.compiler_contract_versions_content_hash,
        legacy.contract_versions_content_hash
    );
}

/// Exact compiler semantics assigned when replaying a pre-profile review.
pub fn legacy_compiler_review_identity_v0() -> CompilerReviewIdentity {
    CompilerReviewIdentity {
        compiler_version: LEGACY_GRAPH_COMPILER_VERSION_V0.to_owned(),
        semantic_profile: LEGACY_GRAPH_COMPILER_SEMANTIC_PROFILE_V0.to_owned(),
        compiler_inputs_schema: LEGACY_COMPILER_INPUTS_SCHEMA_V0.to_owned(),
        contract_versions_content_hash:
            "027b96c63d7feddbe70cbf696718b5946c8b5acb1550a7248bd3ce2b1d698011".to_owned(),
    }
}

#[test]
fn invalid_review_target_is_rejected() {
    let space = fixture_space_with_completion();
    let err = accept_review_morphism(
        &space,
        request(
            NativeReviewTargetKind::Evidence,
            "evidence:not-present",
            ReviewAction::Accept,
            "revision:bad",
        ),
    )
    .expect_err("invalid target");

    assert!(err.message.contains("unknown evidence target"));
}
